"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


__all__ = ["format_account"]


def _is_empty(value: Any) -> bool:
    return value is None or value == ""


def _fixed(value: Any, width: int) -> str:
    text = "" if _is_empty(value) else str(value)
    return text[:width].ljust(width)


def _ann_rev_cents(value: Any) -> int:
    if _is_empty(value):
        value = 0

    text = str(value)
    with localcontext() as context:
        context.prec = max(50, len(text) * 2)
        amount = Decimal(text)
        return int((amount * Decimal(100)).to_integral_value(rounding=ROUND_HALF_UP))


def _zpad(value: int, width: int) -> str:
    text = f"{value:0{width}d}"
    if len(text) != width:
        raise ValueError(f"numeric value does not fit in {width} characters")
    return text


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a terminator."""
    cred_hold = row.get("CRED_HOLD", "")
    if _is_empty(cred_hold) or (
        isinstance(cred_hold, str) and cred_hold.isspace()
    ):
        cred_hold = "N"
    else:
        cred_hold = str(cred_hold)

    create_dt = row.get("CREATE_DT", "")
    if _is_empty(create_dt) or (
        isinstance(create_dt, str) and create_dt.isspace()
    ):
        create_dt = "00000000"
    else:
        create_dt = str(create_dt)

    record = (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _zpad(_ann_rev_cents(row.get("ANN_REV", "")), 15)
        + cred_hold
        + create_dt
    )

    if len(record) != 77:
        raise ValueError("EXPORT_ACCT record must be exactly 77 characters")

    return record
